SELECT artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', artifact.area_batch_id 'areaBatch.id', pa.name 'area.name', areabatch.name 'areaBatch.name', artifact.monomer_id 'monomer.id', pm.name 'monomer.name', artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.scheduling_quantity,0) scheduling_quantity, IFNULL(scheduling.scheduling_quantity*artifact.net_weight,0) scheduling_total_net_weight, IFNULL(scheduling.scheduling_quantity*artifact.gross_weight,0) scheduling_total_gross_weight, artifact.quantity-artifact.subscription_quantity-IFNULL(scheduling.scheduling_quantity,0) un_scheduling_quantity, (artifact.quantity-artifact.subscription_quantity-IFNULL(scheduling.scheduling_quantity,0))*artifact.net_weight un_scheduling_total_net_weight, (artifact.quantity-artifact.subscription_quantity-IFNULL(scheduling.scheduling_quantity,0))*artifact.gross_weight un_scheduling_total_gross_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0 AND area_batch_id IN
#{areaId}
GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id LEFT JOIN plan_area pa ON pa.id = artifact.area_id LEFT JOIN plan_area_batch areabatch ON areabatch.id = artifact.area_batch_id LEFT JOIN plan_monomer pm ON pm.id = artifact.monomer_id WHERE artifact.bool_delete_enum = 0 AND artifact.structure_class_id is not null and artifact.bool_scheduling_enum = 1 AND artifact.area_batch_id IN
#{areaId}
AND artifact.monomer_id = #{monomerId}
AND artifact.structure_class_id IN
#{classId}
AND artifact.structure_class_id = #{structureClassId}
AND artifact.serial_number LIKE concat('%',#{serialNumber},'%')
AND artifact.name IN
#{name}
AND artifact.name LIKE concat('%',#{name},'%')
AND artifact.material LIKE concat('%', #{material},'%')
AND artifact.specification LIKE concat('%', #{specification},'%')
AND artifact.quantity-artifact.subscription_quantity-IFNULL(scheduling.scheduling_quantity,0)>0
AND artifact.smart_line_mark_word is NULL
AND artifact.smart_line_mark_word is NOT NULL
ORDER BY artifact.specification ASC

SELECT classification.id structure_class_id, classification.classification_name name, classification.artifact_type, classification.production_line_type_enum, classification.mes_product_enum, sum(artifact.un_scheduling_quantity) quantity FROM ( SELECT artifact.structure_class_id, artifact.id, artifact.`name`, artifact.serial_number, artifact.material, artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.scheduling_quantity,0) scheduling_quantity, IFNULL(scheduling.scheduling_quantity*artifact.net_weight,0) scheduling_total_net_weight, IFNULL(scheduling.scheduling_quantity*artifact.gross_weight,0) scheduling_total_gross_weight, (artifact.quantity- artifact.subscription_quantity) - IFNULL(scheduling.scheduling_quantity,0) un_scheduling_quantity, (artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0))*artifact.net_weight un_scheduling_total_net_weight, (artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0))*artifact.gross_weight un_scheduling_total_gross_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0
AND area_batch_id IN
#{areaId}
GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id WHERE artifact.bool_delete_enum = 0 and artifact.bool_scheduling_enum = 1
AND artifact.area_batch_id IN
#{areaId}
AND artifact.structure_class_id IN
#{classId}
AND artifact.structure_class_id = #{structureClassId}
AND artifact.name IN
#{name}
AND artifact.quantity - artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0)>0
AND artifact.smart_line_mark_word is NULL
AND artifact.smart_line_mark_word is NOT NULL
) artifact LEFT JOIN sys_structure_classification classification ON artifact.structure_class_id = classification.id WHERE classification.id is not null GROUP BY classification.id , classification.classification_name , classification.production_line_type_enum, classification.artifact_type, classification.mes_product_enum

SELECT artifact.name, sum(artifact.un_scheduling_quantity) quantity FROM ( SELECT artifact.`name`, artifact.quantity-IFNULL(scheduling.scheduling_quantity,0) un_scheduling_quantity FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0
AND area_id IN
#{areaId}
GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id WHERE artifact.bool_delete_enum = 0
AND artifact.area_id IN
#{areaId}
AND artifact.name = #{artName}
AND artifact.quantity-IFNULL(scheduling.scheduling_quantity,0)>0 ) artifact GROUP BY artifact.name

SELECT scheduling.id, artifact.structure_class_id, artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', artifact.area_batch_id 'areaBatch.id', area.name 'area.name', areabatch.name 'areaBatch.name', artifact.monomer_id 'monomer.id', monomer.name 'monomer.name', scheduling.project_id 'project.id', project.name 'project.name', scheduling.workshop_id 'workshop.id', workshop.name 'workshop.name', scheduling.production_line_id 'production_line.id', production_line.name 'production_line.name', production_line.production_line_type_enum 'production_line.production_line_type_enum', scheduling.groups_id 'groups.id', scheduling.ask_complete_time, gro.name 'groups.name', artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, structure_class.id 'structure_class.id', structure_class.classification_name 'structure_class.name', artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.quantity-scheduling.task_quantity,0) scheduling_quantity, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.net_weight,0) scheduling_total_net_weight, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.gross_weight,0) scheduling_total_gross_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN contract_project project ON project .id =scheduling.project_id LEFT JOIN plan_monomer monomer ON monomer.id = scheduling.monomer_id LEFT JOIN plan_area area ON area.id = scheduling.area_id LEFT JOIN plan_area_batch areabatch ON areabatch.id = scheduling.area_batch_id LEFT JOIN mes_building_workshop workshop ON scheduling.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id LEFT JOIN mes_building_groups gro ON scheduling.groups_id=gro.id LEFT JOIN sys_structure_classification structure_class ON artifact.structure_class_id=structure_class.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')
AND scheduling.production_line_id = #{productionLineId}
ORDER BY scheduling.factory_id, scheduling.workshop_id , scheduling.production_line_id , scheduling.groups_id , scheduling.project_id , artifact.monomer_id , artifact.area_id , artifact.area_batch_id , artifact.project_id, artifact.specification, artifact.length

SELECT scheduling.id, artifact.structure_class_id, artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', artifact.area_batch_id 'areaBatch.id', area.name 'area.name', areabatch.name 'areaBatch.name', artifact.monomer_id 'monomer.id', monomer.name 'monomer.name', scheduling.project_id 'project.id', project.name 'project.name', scheduling.workshop_id 'workshop.id', workshop.name 'workshop.name', scheduling.production_line_id 'production_line.id', production_line.name 'production_line.name', production_line.production_line_type_enum 'production_line.production_line_type_enum', scheduling.ask_complete_time, artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, structure_class.id 'structure_class.id', structure_class.classification_name 'structure_class.name', artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.quantity-scheduling.task_quantity,0) scheduling_quantity, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.net_weight,0) scheduling_total_net_weight, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.gross_weight,0) scheduling_total_gross_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN contract_project project ON project .id =scheduling.project_id LEFT JOIN plan_monomer monomer ON monomer.id = scheduling.monomer_id LEFT JOIN plan_area area ON area.id = scheduling.area_id LEFT JOIN plan_area_batch areabatch ON areabatch.id = scheduling.area_batch_id LEFT JOIN mes_building_workshop workshop ON scheduling.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id LEFT JOIN sys_structure_classification structure_class ON artifact.structure_class_id=structure_class.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
and artifact.name = #{artName}
AND scheduling.issue_status=0
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')
AND scheduling.production_line_id = #{productionLineId}
ORDER BY scheduling.factory_id, scheduling.workshop_id , scheduling.production_line_id, scheduling.project_id , artifact.monomer_id , artifact.area_id , artifact.area_batch_id , artifact.project_id, artifact.specification, artifact.length

SELECT scheduling.id, artifact.structure_class_id, artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', area.name 'area.name', artifact.monomer_id 'monomer.id', monomer.name 'monomer.name', scheduling.project_id 'project.id', project.name 'project.name', scheduling.workshop_id 'workshop.id', workshop.name 'workshop.name', scheduling.production_line_id 'production_line.id', production_line.name 'production_line.name', production_line.production_line_type_enum 'production_line.production_line_type_enum', scheduling.ask_complete_time, artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, structure_class.id 'structure_class.id', structure_class.classification_name 'structure_class.name', artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.quantity-scheduling.task_quantity,0) scheduling_quantity, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.net_weight,0) scheduling_total_net_weight, IFNULL((scheduling.quantity-scheduling.task_quantity)*artifact.gross_weight,0) scheduling_total_gross_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN contract_project project ON project .id =scheduling.project_id LEFT JOIN plan_monomer monomer ON monomer.id = scheduling.monomer_id LEFT JOIN plan_area area ON area.id = scheduling.area_id LEFT JOIN mes_building_workshop workshop ON scheduling.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id LEFT JOIN sys_structure_classification structure_class ON artifact.structure_class_id=structure_class.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
and artifact.name = #{artName}
AND scheduling.issue_status=0
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')
AND scheduling.production_line_id = #{productionLineId}
ORDER BY scheduling.factory_id, scheduling.workshop_id , scheduling.production_line_id, scheduling.project_id , artifact.monomer_id , artifact.area_id , artifact.project_id, artifact.specification, artifact.length

SELECT classification.id structure_class_id, classification.classification_name name, classification.artifact_type, classification.production_line_type_enum, sum(artifact.scheduling_quantity) quantity FROM ( SELECT artifact.structure_class_id, artifact.id product_id, IFNULL(scheduling.quantity,0) scheduling_quantity, IFNULL(scheduling.quantity*artifact.net_weight,0) scheduling_total_net_weight, IFNULL(scheduling.quantity*artifact.gross_weight,0) scheduling_total_gross_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON production_line.id = scheduling.production_line_id WHERE scheduling.bool_delete_enum = 0 AND scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND scheduling.groups_id=#{groupsId}
AND production_line.production_line_type_enum = 2
AND production_line.production_line_type_enum = 1
)artifact LEFT JOIN sys_structure_classification classification ON artifact.structure_class_id = classification.id GROUP BY classification.id , classification.classification_name , classification.production_line_type_enum, classification.artifact_type

SELECT classification.id structure_class_id, classification.classification_name name, classification.artifact_type, classification.production_line_type_enum, sum(artifact.scheduling_quantity) quantity FROM ( SELECT artifact.structure_class_id, artifact.id product_id, IFNULL(scheduling.quantity,0) scheduling_quantity, IFNULL(scheduling.quantity*artifact.net_weight,0) scheduling_total_net_weight, IFNULL(scheduling.quantity*artifact.gross_weight,0) scheduling_total_gross_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON production_line.id = scheduling.production_line_id WHERE scheduling.bool_delete_enum = 0 AND scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND scheduling.groups_id=#{groupsId}
AND production_line.production_line_type_enum = 2
AND production_line.production_line_type_enum = 1
)artifact LEFT JOIN sys_structure_classification classification ON artifact.structure_class_id = classification.id GROUP BY classification.id , classification.classification_name , classification.production_line_type_enum, classification.artifact_type

SELECT artifact.name name, sum(IFNULL( scheduling.quantity, 0 )) quantity FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON production_line.id = scheduling.production_line_id WHERE scheduling.bool_delete_enum = 0 AND scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND scheduling.production_line_id = #{productionLineId}
GROUP BY artifact.name

SELECT sum(artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0)) quantity, sum((artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0))*artifact.net_weight) total_net_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0
AND area_batch_id IN
#{areaId}
GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id WHERE artifact.bool_delete_enum = 0
AND artifact.area_batch_id IN
#{areaId}
and artifact.monomer_id = #{monomerId}
AND artifact.structure_class_id IN
#{classId}
AND artifact.structure_class_id = #{structureClassId}
AND artifact.name IN
#{name}
AND artifact.serial_number LIKE concat('%',#{serialNumber},'%')
AND artifact.specification LIKE concat('%', #{specification},'%')
AND artifact.material LIKE concat('%', #{material},'%')
AND artifact.name LIKE concat('%',#{name},'%')
AND artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0)>0

SELECT IFNULL(sum(scheduling.quantity-scheduling.task_quantity),0) quantity, IFNULL(sum((scheduling.quantity-scheduling.task_quantity)*artifact.net_weight),0)total_net_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND scheduling.production_line_id = #{productionLineId}
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')

SELECT IFNULL(sum(scheduling.quantity-scheduling.task_quantity),0) quantity, IFNULL(sum((scheduling.quantity-scheduling.task_quantity)*artifact.net_weight),0)total_net_weight, max(scheduling.ask_complete_time) AS maxAskCompleteTime, min(scheduling.ask_complete_time) AS minAskCompleteTime FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')
and artifact.name = #{artName}
AND scheduling.production_line_id = #{productionLineId}

SELECT DISTINCT classification.production_line_type_enum FROM ( SELECT artifact.structure_class_id FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON production_line.id = scheduling.production_line_id WHERE scheduling.bool_delete_enum = 0 AND scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND scheduling.issue_status=0
)artifact LEFT JOIN sys_structure_classification classification ON artifact.structure_class_id = classification.id

SELECT workshop_id 'workshop.id', workshop_name 'workshop.name', production_line_id 'production_line.id', production_line_name 'production_line.name', groups_id 'groups.id', groups_name 'groups.name', IFNULL( sum( quantity ), 0 ) 'mete.quantity', IFNULL( sum( total_net_weight ), 0 ) 'mete.net_weight' FROM ( SELECT workshop.id workshop_id, workshop.`name` workshop_name, production_line.id production_line_id, production_line.`name` production_line_name, gro.id groups_id, gro.`name` groups_name, scheduling.quantity - scheduling.task_quantity quantity, ( scheduling.quantity - scheduling.task_quantity )* artifact.net_weight total_net_weight FROM mes_building_artifact_scheduling scheduling LEFT JOIN tech_artifact artifact ON scheduling.product_id = artifact.id LEFT JOIN mes_building_production_line production_line ON scheduling.production_line_id=production_line.id LEFT JOIN mes_building_workshop workshop ON scheduling.workshop_id=workshop.id LEFT JOIN mes_building_groups gro ON scheduling.groups_id=gro.id WHERE scheduling.bool_delete_enum = 0 and scheduling.quantity-scheduling.task_quantity>0 AND scheduling.area_batch_id IN
#{areaId}
AND artifact.structure_class_id = #{structureClassId}
AND scheduling.issue_status=0
AND artifact.serial_number like CONCAT('%', #{serialNumber},'%')
AND production_line.production_line_type_enum = 2
AND production_line.production_line_type_enum = 1
) AS a GROUP BY workshop_id, workshop_name, production_line_id, production_line_name, groups_id, groups_name

SELECT artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', pa.name 'area.name', artifact.monomer_id 'monomer.id', pm.name 'monomer.name', cp.id 'project.id', cp.name 'project.name', artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.artifact_type, artifact.structure_class_id, artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0) quantity, (artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0))*artifact.net_weight total_net_weight, (artifact.quantity- artifact.subscription_quantity - IFNULL(scheduling.scheduling_quantity,0))*artifact.gross_weight total_gross_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0 AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id LEFT JOIN plan_area pa ON pa.id = artifact.area_id LEFT JOIN plan_monomer pm ON pm.id = artifact.monomer_id LEFT JOIN contract_project cp ON cp.id = artifact.project_id WHERE artifact.bool_delete_enum = 0 and artifact.project_id = #{projectId} AND artifact.structure_class_id is not null
AND artifact.monomer_id = #{monomerId}
AND artifact.area_id = #{areaId}
AND structure_class_id = #{structureClassId}
AND artifact.serial_number LIKE concat('%',#{serialNumber},'%')
AND artifact.name LIKE concat('%',#{name},'%')
AND artifact.material LIKE concat('%', #{material},'%')
AND artifact.specification LIKE concat('%', #{specification},'%')
AND artifact.quantity-artifact.subscription_quantity -IFNULL(scheduling.scheduling_quantity,0) > 0 ORDER BY artifact.specification,artifact.id ASC

SELECT shop.`name` 'shopName', shop.`name` 'shopName', line.`name` 'lineName', IFNULL( sum( sche.task_quantity ), 0 ) 'scheduledQuantity', ROUND( IFNULL( sum( sche.task_quantity * art.net_weight ), 0 )/ 1000, 3 ) 'scheduledWeight', sum(art.quantity - IFNULL( sche.task_quantity, 0 )) 'unScheduledQuantity', ROUND( sum(( art.quantity - IFNULL( sche.task_quantity, 0 )) * art.net_weight )/ 1000, 3 ) 'unScheduledWeight', sum( task.complete_quantity ) 'completeQuantity', ROUND( sum( task.complete_quantity * art.net_weight )/ 1000, 3 ) 'completeWeight' FROM tech_artifact art INNER JOIN mes_building_artifact_scheduling sche ON sche.product_id = art.id AND sche.bool_delete_enum = 0 LEFT JOIN mes_building_task task on sche.id = task.scheduling_id AND task.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop ON sche.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON sche.production_line_id = line.id AND line.bool_delete_enum = 0 WHERE art.bool_delete_enum = 0
and shop.id = #{workshopId}
and art.project_id = #{projectId}
GROUP BY shop.`name`, line.`name`
